aph {\"className\":\"blog-desc\"} -->\n<p class=\"blog-desc\">Sharing my journey as an IT student, including my learning experiences, academic projects, and continuous growth in technology.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"blog-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-card\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your article image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":157,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"blog-img\"} -->\n<figure class=\"wp-block-image size-large blog-img\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/833862810_122145724545063533_6602061285084533491_n-768x1024-1.jpg\" alt=\"\" class=\"wp-image-157\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:group {\"className\":\"blog-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-content\"><!-- wp:html -->\n<div class=\"blog-meta\"><span><i class=\"far fa-calendar\" aria-hidden=\"true\"></i> Add date</span><span><i class=\"far fa-user\" aria-hidden=\"true\"></i> Member 3</span></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"blog-title\"} -->\n<h3 class=\"wp-block-heading blog-title\">Creativity Beyond Technology</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"blog-desc\"} -->\n<p class=\"blog-desc\">A showcase of my creativity and passion for nail artistry, which I have pursued as a side career since 2022.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-se