(32, 1, '2026-11-05 08:17:02', '2026-11-05 08:17:02', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m a</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">WEB3 ENTHUSIAST</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":17,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/final_porf-724x1024.jpg\" alt=\"\" class=\"wp-image-17\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">Passionate about building and growing Web3 communities while contributing to the future of decentralized ecosystems. Specializing in NFT trading analysis, community management, and Web3 engagement strategies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":18,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image size-full image-wrapper\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/a8964640-e95d-42ff-9b64-e57954fac722-1.jpg\" alt=\"\" class=\"wp-image-18\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">4</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"10rem\",\"bottom\":\"10rem\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:10rem;padding-bottom:10rem\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>I\'m a passionate Web3 enthusiast with 4 years of hands-on experience in the blockchain ecosystem. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>My journey began with active participation in crypto communities, where I developed expertise in managing and growing Web3 communities.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>Beyond development, I\'m an experienced trader specializing in meme coins and NFTs, with a keen eye for market trends and opportunities. I combine technical knowledge with trading experience to navigate the dynamic Web3 landscape effectively.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-info\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\" style=\"margin-top:var(--wp--preset--spacing--80);margin-bottom:var(--wp--preset--spacing--80)\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Tyrone Parreño | Dev Venci</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> tyrone.web3@proton.me</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> 2 Years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> Blockchain</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> Philippines, Opol</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-section section-services\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY SKILLS</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"services-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group services-grid\"><!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-users\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Community Management</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Experienced community building and engagement strategies for Web3 projects. Grow and manage active communities around your blockchain project.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-line\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Crypto Trading</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Specialized trading strategies for meme coins and NFTs. Market analysis and trading signals to maximize your crypto investments.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-palette\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">NFT Development</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">NFT solutions from smart contracts to marketplaces. Create, deploy, and trade non-fungible tokens on various blockchains.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-comments\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Crypto Community Building</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Expert strategies for growing and engaging Web3 communities. From Discord setup to community engagement campaigns and influencer partnerships.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-pie\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">NFT Trading Analysis</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Comprehensive NFT market analysis including floor price tracking, rarity scoring, and trading strategy development for collections.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-graduation-cap\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Web3 Consultation</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Strategic consultation on blockchain implementation, tokenomics design, and Web3 transition for businesses and startups.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-portfolio\",\"layout\":{\"type\":\"default\"},\"anchor\":\"portfolio\"} -->\n<section id=\"portfolio\" class=\"wp-block-group section devenci-section section-portfolio\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY PORTFOLIO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:devenci/portfolio-grid -->\n<!-- wp:devenci/portfolio-item {\"category\":\"Community\",\"imageId\":20,\"imageAlt\":\"plume\",\"link\":\"https://x.com/plumenetwork\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"portfolio-title\"} -->\n<h3 class=\"wp-block-heading portfolio-title\">Plume\'s Goon NFT mint for the Testers</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Contributed to the growth of the Plume community by inviting 1k–5k new users.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Analysis\",\"imageId\":22,\"imageAlt\":\"bonkta\",\"link\":\"https://dexscreener.com/\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"portfolio-title\"} -->\n<h3 class=\"wp-block-heading portfolio-title\">Meme Coin Trading</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Achieved 10x–1000x ROI by strategically sniping meme coins.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"NFT\",\"imageId\":23,\"imageAlt\":\"jaks\",\"link\":\"https://x.com/jackson_app\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"portfolio-title\"} -->\n<h3 class=\"wp-block-heading portfolio-title\">Jackson Sharkz</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Guided and onboarded a significant number of users during the Jackson NFT airdrop.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Community\",\"imageId\":26,\"imageAlt\":\"signad\",\"link\":\"https://x.com/ethsign\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"portfolio-title\"} -->\n<h3 class=\"wp-block-heading portfolio-title\">Sign Protocol Influencer Partnerships</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Collaborated with co-sign influencers to strategically grow the Sign Protocol community.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n<!-- /wp:devenci/portfolio-grid --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-resume\",\"layout\":{\"type\":\"default\"},\"anchor\":\"resume\"} -->\n<section id=\"resume\" class=\"wp-block-group section devenci-section section-resume\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY RESUME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"resume-container\"} -->\n<div class=\"wp-block-columns resume-container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"resume-date\"} -->\n<p class=\"resume-date\">2024 - 2027</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"resume-title\"} -->\n<h4 class=\"wp-block-heading resume-title\">BS in Information Technology</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"resume-company\"} -->\n<p class=\"resume-company\">Opol Community College</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"resume-desc\"} -->\n<p class=\"resume-desc\">Gaining comprehensive knowledge in technology and development coding to enhance my Web3 expertise.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Experience</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"resume-date\"} -->\n<p class=\"resume-date\">2022 - Present</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"resume-title\"} -->\n<h4 class=\"wp-block-heading resume-title\">Web3 Community Manager</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"resume-company\"} -->\n<p class=\"resume-company\">Web3 Creator</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"resume-desc\"} -->\n<p class=\"resume-desc\">Managed and grew Web3 communities, developed engagement strategies, and coordinated influencer partnerships for NFT projects.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"resume-date\"} -->\n<p class=\"resume-date\">2024 - Present</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"resume-title\"} -->\n<h4 class=\"wp-block-heading resume-title\">Trading Analyst</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"resume-company\"} -->\n<p class=\"resume-company\">Market Insights</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"resume-desc\"} -->\n<p class=\"resume-desc\">Provided TREND market analysis, price tracking, and trading strategy development.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"skills-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group skills-content\"><!-- wp:heading {\"level\":3,\"className\":\"skills-title\"} -->\n<h3 class=\"wp-block-heading skills-title\">Technical Skills</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"className\":\"skills-grid\"} -->\n<div class=\"wp-block-columns skills-grid\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"skill-category\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group skill-category\"><!-- wp:devenci/skill-bar {\"label\":\"Community Management\",\"percent\":95} /-->\n\n<!-- wp:devenci/skill-bar {\"label\":\"NFT Trading Analysis\",\"percent\":90} /-->\n\n<!-- wp:devenci/skill-bar {\"label\":\"Market Trend Analysis\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"skill-category\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group skill-category\"><!-- wp:devenci/skill-bar {\"label\":\"NFT Market Dynamics\",\"percent\":95} /-->\n\n<!-- wp:devenci/skill-bar {\"label\":\"Community Growth Strategies\",\"percent\":90} /-->\n\n<!-- wp:devenci/skill-bar {\"label\":\"Influencer Partnerships\",\"percent\":85} /-->\n\n<!-- wp:devenci/skill-bar {\"label\":\"Tokenomics Analysis\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-blog\",\"layout\":{\"type\":\"default\"},\"anchor\":\"blog\"} -->\n<section id=\"blog\" class=\"wp-block-group section devenci-section section-blog\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">LATEST ARTICLES</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"blog-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-grid\"><!-- wp:group {\"className\":\"blog-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-card\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your article image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":25,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"blog-img\"} -->\n<figure class=\"wp-block-image size-full blog-img\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/mtr.png\" alt=\"\" class=\"wp-image-25\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"blog-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-content\"><!-- wp:html -->\n<div class=\"blog-meta\"><span><i class=\"far fa-calendar\" aria-hidden=\"true\"></i> April 15, 2025</span><span><i class=\"far fa-user\" aria-hidden=\"true\"></i> Dev Venci</span></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"blog-title\"} -->\n<h3 class=\"wp-block-heading blog-title\">Memecoin Trading Analysis</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"blog-desc\"} -->\n<p class=\"blog-desc\">Memecoins like Dogecoin, Shiba Inu, and the newer generation such as PEPE and WIF have shown that viral momentum can outperform fundamentals…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"blog-link\"} -->\n<p class=\"blog-link\"><a href=\"https://open.substack.com/pub/devvenci/p/memecoin-trading-analysis\">Read More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"blog-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-card\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your article image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":27,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"blog-img\"} -->\n<figure class=\"wp-block-image size-full blog-img\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/trendm.png\" alt=\"\" class=\"wp-image-27\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"blog-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-content\"><!-- wp:html -->\n<div class=\"blog-meta\"><span><i class=\"far fa-calendar\" aria-hidden=\"true\"></i> February 21, 2025</span><span><i class=\"far fa-user\" aria-hidden=\"true\"></i> Dev Venci</span></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"blog-title\"} -->\n<h3 class=\"wp-block-heading blog-title\">Market Trend</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"blog-desc\"} -->\n<p class=\"blog-desc\">The broader crypto market is currently in a consolidation phase following a sharp bull run in Q1 2025. Bitcoin and Ethereum are holding key support levels, while Layer 2 tokens…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"blog-link\"} -->\n<p class=\"blog-link\"><a href=\"https://open.substack.com/pub/devvenci/p/market-trend\">Read More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"blog-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-card\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your article image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":28,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"blog-img\"} -->\n<figure class=\"wp-block-image size-full blog-img\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/web12.png\" alt=\"\" class=\"wp-image-28\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"blog-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group blog-content\"><!-- wp:html -->\n<div class=\"blog-meta\"><span><i class=\"far fa-calendar\" aria-hidden=\"true\"></i> January 26, 2025</span><span><i class=\"far fa-user\" aria-hidden=\"true\"></i> Dev Venci</span></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"blog-title\"} -->\n<h3 class=\"wp-block-heading blog-title\">How Web3 Is Expanding</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"blog-desc\"} -->\n<p class=\"blog-desc\">Web3 continues to evolve beyond just decentralized finance. We\'re now seeing significant adoption in gaming (GameFi), social media (decentralized social platforms)…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"blog-link\"} -->\n<p class=\"blog-link\"><a href=\"https://open.substack.com/pub/devvenci/p/how-web3-is-expanding\">Read More</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-contact\",\"layout\":{\"type\":\"default\"},\"anchor\":\"contact\"} -->\n<section id=\"contact\" class=\"wp-block-group section devenci-section section-contact\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">CONTACT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"contact-content\"} -->\n<div class=\"wp-block-columns contact-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"contact-info\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-info\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Let\'s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"contact-details\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-details\"><!-- wp:group {\"className\":\"contact-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-item\"><!-- wp:html -->\n<div class=\"contact-icon\"><i class=\"fas fa-map-marker-alt\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"contact-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-text\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Location</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Opol, Mis OR, Philippines</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"contact-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-item\"><!-- wp:html -->\n<div class=\"contact-icon\"><i class=\"fas fa-envelope\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"contact-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-text\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Email</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>tyrone.web3@proton.me</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"contact-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-item\"><!-- wp:html -->\n<div class=\"contact-icon\"><i class=\"fas fa-phone-alt\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"contact-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-text\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Phone</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>+639 750 443 410</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Follow Me</h3>\n<!-- /wp:heading -->\n\n<!-- wp:social-links {\"className\":\"social-links\"} -->\n<ul class=\"wp-block-social-links social-links\"><!-- wp:social-link {\"url\":\"https://x.com/venciiOnweb3_\",\"service\":\"x\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://github.com/580019\",\"service\":\"github\"} /-->\n\n<!-- wp:social-link {\"url\":\"http://www.linkedin.com/in/tyroneweb3\",\"service\":\"linkedin\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://discord.com/users/1326148612836818993\",\"service\":\"discord\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://t.me/DEVVenci\",\"service\":\"telegram\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:devenci/contact-form /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->', 'Tyrone Parreño | Dev Venci', '', 'inherit', 'closed', 'closed', '', '7-revision-v1', '', '', '2026-11-05 08:17:02', '2026-11-05 08:17:02', '', 7, 'http://localhost/team-ku/wordpress/?p=32', 0, 'revision', '', 0),
