(47, 1, '2026-11-05 08:36:00', '2026-11-05 08:36:00', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m a</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">WEB3 ENTHUSIAST</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":17,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/final_porf-724x1024.jpg\" alt=\"\" class=\"wp-image-17\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">Passionate about building and growing Web3 communities while contributing to the future of decentralized ecosystems. Specializing in NFT trading analysis, community management, and Web3 engagement strategies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":40,\"aspectRatio\":\"0.5627782724844167\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image size-full image-wrapper\"><img src=\"https://team-ku.tech/wordpress/wp-content/uploads/2026/11/67c2d174-a53f-4146-b8f4-a1a67328f734-removebg-preview.png\" alt=\"\" class=\"wp-image-40\" style=\"aspect-ratio:0.5627782724844167\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">4</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"10rem\",\"bottom\":\"10rem\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:10rem;padding-bottom:10rem\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>I\'m a passionate Web3 enthusiast with 4 years of hands-on experience in the blockchain ecosystem. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>My journey began with active participation in crypto communities, where I developed expertise in managing and growing Web3 communities.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Beyond development, I\'m an experienced trader specializing in meme coins and NFTs, with a keen eye for market trends and opportunities. I combine technical knowledge with trading experience to navigate the dynamic Web3 landscape effectively.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:group {\"className\":\"about-info\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\" style=\"margin-top:var(--wp--preset--spacing--80);margin-bottom:var(--wp--preset--spacing--80)\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Tyrone Parreño | Dev Venci</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> tyrone.web3@proton.me</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> 2 Years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> Blockchain</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> Philippines, Opol</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-section section-services\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY SKILLS</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"services-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group services-grid\"><!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-users\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Community Management</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Experienced community building and engagement strategies for Web3 projects. Grow and manage active communities around your blockchain project.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-line\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Crypto Trading</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Specialized trading strategies for meme coins and NFTs. Market analysis and trading signals to maximize your crypto investments.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-palette\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">NFT Development</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">NFT solutions from smart contracts to marketplaces. Create, deploy, and trade non-fungible tokens on various blockchains.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-comments\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Crypto Community Building</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Expert strategies for growing and engaging Web3 communities. From Discord setup to community engagement campaigns and influencer partnerships.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-pie\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">NFT Trading Analysis</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Comprehensive NFT market analysis including floor price tracking, rarity scoring, and trading strategy development for collections.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\