(50, 1, '2026-11-05 08:37:46', '2026-11-05 08:37:46', '<!-- wp:group {\"className\":\"group-main\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group group-main\"><!-- wp:group {\"className\":\"group-intro\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group group-intro\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Meet the</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">TEAM-KU 4A</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"group-tagline\"} -->\n<p class=\"group-tagline\">Pick a member to explore their portfolio.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"members\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group members\"><!-- wp:devenci/member-card {\"url\":\"https://team-ku.tech/wordpress/index.php/member-1/\",\"imageId\":49,\"imageAlt\":\"a8964640-e95d-42ff-9b64-e57954fac722__1_-removebg-preview\"} -->\n<!-- wp:paragraph -->\n<p>Tyrone pARREÑO<em>Dev Venci</em></p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/member-card -->\n\n<!-- wp:devenci/member-card {\"url\":\"https://team-ku.tech/wordpress/index.php/member-2/\",\"imageAlt\":\"Member 2\",\"delay\":\"0.6s\"} -->\n<!-- wp:paragraph -->\n<p>MembEr 2<em>Role</em></p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/member-card -->\n\n<!-- wp:devenci/member-card {\"url\":\"https://team-ku.tech/wordpress/index.php/member-3/\",\"imageAlt\":\"Member 3\",\"delay\":\"1.2s\"} -->\n<!-- wp:paragraph -->\n<p>Member 3<em>Role</em></p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/member-card -->\n\n<!-- wp:devenci/member-card {\"url\":\"https://team-ku.tech/wordpress/index.php/member-4/\",\"imageAlt\":\"Member 4\",\"delay\":\"1.8s\"} -->\n<!-- wp:paragraph -->\n<p>Member 4<em>Role</em></p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/member-card --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'TeamKU-4A', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-05 08:37:46', '2026-11-05 08:37:46', '', 11, 'http://localhost/team-ku/wordpress/?p=50', 0, 'revision', '', 0);
