(80, 2, '2026-11-05 11:56:18', '2026-11-05 11:56:18', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">Half Human</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":73,\"scale\":\"cover\",\"focalPoint\":{\"x\":0.2,\"y\":0.2},\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Masked-Young-Man-Cutout-Portrait-1-768x1024-1.png\" alt=\"\" class=\"wp-image-73\" style=\"object-fit:cover;object-position:20% 20%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">Replace this introduction with a short summary of who you are, what you do, and the kind of work you enjoy.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":67,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image size-large image-wrapper\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Masked-Young-Man-Cutout-Portrait-768x1024-1.png\" alt=\"\" class=\"wp-image-67\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:var(--wp--preset--spacing--80);padding-bottom:0;padding-left:var(--wp--preset--spacing--80)\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">4</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>I am a Telecommunications Radio Frequency (RF) Engineer without license, <strong>4 years of professional experience</strong> in the telecommunications industry. Throughout my career, I have gained hands-on experience in RF operations, network optimization, troubleshooting, and maintenance of telecommunications equipment.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I have developed a strong understanding of radio frequency systems, wireless network performance, and telecommunications infrastructure. I am experienced in working in field environments, identifying technical issues, and providing effective solutions to ensure reliable network performance.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I am a hardworking, adaptable, and detail-oriented professional who is committed to continuous learning and improving my technical skills. I am passionate about telecommunications technology and always willing to take on new challenges that contribute to my professional growth and the success of the organization.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-info\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Reymund Brondo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> occ.brondo.reymund@gmail.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> Add years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> 4G / 5G Optimization</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> Buhangin Davao City </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-sect