(90, 2, '2026-11-05 12:22:38', '2026-11-05 12:22:38', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">Half Human</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":73,\"scale\":\"cover\",\"focalPoint\":{\"x\":0.2,\"y\":0.2},\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Masked-Young-Man-Cutout-Portrait-1-768x1024-1.png\" alt=\"\" class=\"wp-image-73\" style=\"object-fit:cover;object-position:20% 20%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">Living a simple, happy life and making the most of every moment. Just enjoying the journey, staying positive, and living life to the fullest.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":67,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image size-large image-wrapper\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Masked-Young-Man-Cutout-Portrait-768x1024-1.png\" alt=\"\" class=\"wp-image-67\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:var(--wp--preset--spacing--80);padding-bottom:0;padding-left:var(--wp--preset--spacing--80)\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">4</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>I am a Telecommunications Radio Frequency (RF) Engineer without license, <strong>4 years of professional experience</strong> in the telecommunications industry. Throughout my career, I have gained hands-on experience in RF operations, network optimization, troubleshooting, and maintenance of telecommunications equipment.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I have developed a strong understanding of radio frequency systems, wireless network performance, and telecommunications infrastructure. I am experienced in working in field environments, identifying technical issues, and providing effective solutions to ensure reliable network performance.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I am a hardworking, adaptable, and detail-oriented professional who is committed to continuous learning and improving my technical skills. I am passionate about telecommunications technology and always willing to take on new challenges that contribute to my professional growth and the success of the organization.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-info\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Reymund Brondo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> occ.brondo.reymund@gmail.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> Add years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> 4G / 5G Optimization</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> Buhangin Davao City </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-section section-services\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY SKILLS</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"services-grid\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group services-grid\"><!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\">\n    <i class=\"fas fa-tower-broadcast\" aria-hidden=\"true\"></i>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">RF Network Optimization</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Analyzing and improving network performance, coverage, capacity, and signal quality.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\">\n    <i class=\"fas fa-car\" aria-hidden=\"true\"></i>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Drive Test Analysis</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Conducting drive tests and analyzing signal parameters such as RSRP, RSRQ, SINR, and RSSI.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\">\n    <i class=\"fas fa-screwdriver-wrench\" aria-hidden=\"true\"></i>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">RF Troubleshooting</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Identifying and resolving network issues, interference, coverage gaps, and call-drop problems.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\">\n    <i class=\"fas fa-chart-line\" aria-hidden=\"true\"></i>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Network Performance Monitoring</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Monitoring KPIs, evaluating network performance, and implementing optimization strategies to improve user experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-portfolio\",\"layout\":{\"type\":\"default\"},\"anchor\":\"portfolio\"} -->\n<section id=\"portfolio\" class=\"wp-block-group section devenci-section section-portfolio\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY PORTFOLIO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:devenci/portfolio-grid -->\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":85,\"imageAlt\":\"455g opt\"} -->\n<!-- wp:paragraph -->\n<p>4G / 5G Optimization</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Optimized 4G and 5G network performance by analyzing RF KPIs, improving coverage and signal quality, and reducing interference, resulting in enhanced network reliability and user experience.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":87,\"imageAlt\":\"tower\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"portfolio-title\"} -->\n<h3 class=\"wp-block-heading portfolio-title\">Telecom Tower Installation &amp; Maintenance</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">Performed tower inspection, equipment maintenance, and antenna system checks to ensure reliable signal transmission, network stability, and optimal telecommunications coverage.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n<!-- /wp:devenci/portfolio-grid --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-resume\",\"layout\":{\"type\":\"default\"},\"anchor\":\"resume\"} -->\n<section id=\"resume\" class=\"wp-block-group section devenci-section section-resume\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY RESUME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"resume-container\"} -->\n<div class=\"wp-block-columns resume-container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"resume-date\"} -->\n<p class=\"resume-date\">Add dates</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"resume-title\"} -->\n<h4 class=\"wp-block-heading resume-title\">BS in Information Technology</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"resume-company\"} -->\n<p class=\"resume-company\">Opol Community College</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"resume-desc\"} -->\n<p class=\"resume-desc\">Studied telecommunications, electronics, and networking fundamentals, developing technical knowledge and problem-solving skills relevant to the telecommunications industry.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Experience</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"res