n<!-- wp:group {\"className\":\"contact-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group contact-text\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Phone</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Add your phone number</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Follow Me</h3>\n<!-- /wp:heading -->\n\n<!-- wp:social-links {\"className\":\"social-links\"} -->\n<ul class=\"wp-block-social-links social-links\"><!-- wp:social-link {\"url\":\"https://x.com\",\"service\":\"x\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://github.com\",\"service\":\"github\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.linkedin.com\",\"service\":\"linkedin\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:devenci/contact-form /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->', 'Member 2', '', 'inherit', 'closed', 'closed', '', '8-revision-v1', '', '', '2026-11-05 12:34:13', '2026-11-05 12:34:13', '', 8, 'https://team-ku.tech/?p=99', 0, 'revision', '', 0);
