(128, 3, '2026-11-06 00:28:08', '2026-11-06 00:28:08', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">Ms. Ivy</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":126,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Polished-Professional-Portrait-1024x1024.png\" alt=\"\" class=\"wp-image-126\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">Replace this introduction with a short summary of who you are, what you do, and the kind of work you enjoy.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image image-wrapper\"><img alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">0</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>Use this space to tell visitors about your background, the projects you have worked on, and what you are currently learning.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Add a second paragraph with the work you enjoy most, the tools you use, and the kind of collaborations you are looking for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-info\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Ivy M. Velasco</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> occ.velasco.ivy@gmail.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> Add years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> Add specialty</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> El Salvador City</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-section section-services\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY SKILLS</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"services-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group services-grid\"><!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-users\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Add a Skill</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Describe this skill and the value you bring to a team or project.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-line\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"serv