(160, 3, '2026-11-06 10:16:35', '2026-11-06 10:16:35', '<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-home devenci-home\",\"layout\":{\"type\":\"default\"},\"anchor\":\"home\"} -->\n<section id=\"home\" class=\"wp-block-group section devenci-section section-home devenci-home\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"home-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group home-content\"><!-- wp:heading {\"level\":3,\"className\":\"subtitle typing-subtitle\"} -->\n<h3 class=\"wp-block-heading subtitle typing-subtitle\">Hi There! I\'m</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"glitch-title\"} -->\n<h1 class=\"wp-block-heading glitch-title\">Ms. Aybe</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your profile image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":126,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"profile-hex\"} -->\n<figure class=\"wp-block-image size-large profile-hex\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Polished-Professional-Portrait-1024x1024.png\" alt=\"\" class=\"wp-image-126\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"className\":\"typing-text\"} -->\n<p class=\"typing-text\">I’m a creative and hardworking individual with a passion for technology and beauty. I enjoy learning new skills, exploring ideas, and expressing my creativity through my work as a nail technician.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"cta-buttons\"} -->\n<div class=\"wp-block-buttons cta-buttons\"><!-- wp:button {\"className\":\"btn primary-btn icon-arrow\"} -->\n<div class=\"wp-block-button btn primary-btn icon-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"#about\">Learn More</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"btn secondary-btn icon-briefcase\"} -->\n<div class=\"wp-block-button btn secondary-btn icon-briefcase\"><a class=\"wp-block-button__link wp-element-button\" href=\"#portfolio\">View Portfolio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"scroll-indicator\" aria-hidden=\"true\"><span class=\"mouse\"><span class=\"wheel\"></span></span><span class=\"scroll-text\">Scroll Down</span></div>\n<!-- /wp:html --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-about\",\"layout\":{\"type\":\"default\"},\"anchor\":\"about\"} -->\n<section id=\"about\" class=\"wp-block-group section devenci-section section-about\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">ABOUT ME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"about-content\"} -->\n<div class=\"wp-block-columns about-content\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-image\"><!-- wp:paragraph {\"className\":\"image-placeholder-text\"} -->\n<p class=\"image-placeholder-text\">Add your about image</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":129,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"image-wrapper\"} -->\n<figure class=\"wp-block-image size-large image-wrapper\"><img src=\"https://team-ku.tech/wp-content/uploads/2026/11/Polished-Professional-Portrait-1-1024x1024.png\" alt=\"\" class=\"wp-image-129\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"experience-box\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group experience-box\"><!-- wp:heading {\"level\":3,\"className\":\"experience-number\"} -->\n<h3 class=\"wp-block-heading experience-number\">4</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"experience-text\"} -->\n<p class=\"experience-text\">Years of Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"about-text\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-text\"><!-- wp:paragraph -->\n<p>I am an Information Technology student interested in technology, digital tools, and continuous learning. I enjoy exploring new skills and working on projects that help me grow professionally. I also work as a part-time nail technician, a side career I have pursued since 2022.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I enjoy creative and hands-on work, problem-solving, and learning new technologies. I am open to collaborations and opportunities that allow me to gain experience, share ideas, and develop my skills.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"about-info\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group about-info\"><!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Name:</strong> Ivy M. Velasco</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Email:</strong> occ.velasco.ivy@gmail.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Experience:</strong> 4 years</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Specialty:</strong> Digital Skills | Creative Design</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"info-item\"} -->\n<p class=\"info-item\"><strong>Location:</strong> El Salvador City</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"about-cta\"} -->\n<div class=\"wp-block-buttons about-cta\"><!-- wp:button {\"className\":\"btn primary-btn icon-paper-plane\"} -->\n<div class=\"wp-block-button btn primary-btn icon-paper-plane\"><a class=\"wp-block-button__link wp-element-button\" href=\"#contact\">Contact Me</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-services\",\"layout\":{\"type\":\"default\"},\"anchor\":\"services\"} -->\n<section id=\"services\" class=\"wp-block-group section devenci-section section-services\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY SKILLS</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"services-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group services-grid\"><!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-users\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Communication Skills</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Able to communicate ideas clearly, work well with others, and contribute positively to team projects.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-line\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Adaptability</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Willing to learn new tools and technologies, adapt to different tasks, and continuously improve my skills.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-palette\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Creativity &amp; Design</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Creative and detail-oriented, with experience in designing nail art and developing visually appealing concepts.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"service-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group service-card\"><!-- wp:html -->\n<div class=\"service-icon\"><i class=\"fas fa-chart-pie\" aria-hidden=\"true\"></i></div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"service-title\"} -->\n<h3 class=\"wp-block-heading service-title\">Microsoft Office</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"service-desc\"} -->\n<p class=\"service-desc\">Proficient in using Microsoft Word, PowerPoint, and basic Excel for creating documents, presentations, and organizing information.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-portfolio\",\"layout\":{\"type\":\"default\"},\"anchor\":\"portfolio\"} -->\n<section id=\"portfolio\" class=\"wp-block-group section devenci-section section-portfolio\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY PORTFOLIO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:devenci/portfolio-grid -->\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":150,\"imageAlt\":\"fd068ccc-5171-4d16-aa45-0fa5a23a9967\"} -->\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">A collection of my recent nail art work, showcasing my creativity, attention to detail, and experience as a part-time nail technician since 2022. Each design reflects my passion for beauty and creative expression.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":151,\"imageAlt\":\"05fd37da-c028-4a7a-8e2d-8f6374be2026\"} -->\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">A collection of my recent nail art work, showcasing my creativity, attention to detail, and experience as a part-time nail technician since 2022. Each design reflects my passion for beauty and creative expression.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":152,\"imageAlt\":\"867852732_122148567657063533_5451393078347978075_n\"} -->\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">A collection of my recent nail art work, showcasing my creativity, attention to detail, and experience as a part-time nail technician since 2022. Each design reflects my passion for beauty and creative expression.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n\n<!-- wp:devenci/portfolio-item {\"category\":\"Project\",\"imageId\":153,\"imageAlt\":\"833391816_122145724467063533_1233342894130267052_n\"} -->\n<!-- wp:paragraph {\"className\":\"portfolio-category\"} -->\n<p class=\"portfolio-category\">A collection of my recent nail art work, showcasing my creativity, attention to detail, and experience as a part-time nail technician since 2022. Each design reflects my passion for beauty and creative expression.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:devenci/portfolio-item -->\n<!-- /wp:devenci/portfolio-grid --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section devenci-section section-resume\",\"layout\":{\"type\":\"default\"},\"anchor\":\"resume\"} -->\n<section id=\"resume\" class=\"wp-block-group section devenci-section section-resume\"><!-- wp:group {\"className\":\"container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group container\"><!-- wp:group {\"className\":\"section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group section-header\"><!-- wp:heading {\"className\":\"section-title glitch-title\"} -->\n<h2 class=\"wp-block-heading section-title glitch-title\">MY RESUME</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"resume-container\"} -->\n<div class=\"wp-block-columns resume-container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"className\":\"resume-date\"} -->\n<p class=\"resume-date\">2023-2028</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"resume-title\"} -->\n<h4 class=\"wp-block-heading resume-title\">Information Technology</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"resume-company\"} -->\n<p class=\"resume-company\">Opol Community College</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"resume-desc\"} -->\n<p class=\"resume-desc\">Currently studying Information Technology, gaining knowledge in computer systems, programming fundamentals, and digital technologies. This education helps me develop technical skills, problem-solving abilities, and a foundation for future opportunities in the IT field.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"resume-section-title\"} -->\n<h3 class=\"wp-block-heading resume-section-title\">Experience</h3>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"resume-timeline\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-timeline\"><!-- wp:group {\"className\":\"resume-item\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group resume-item\"><!-- wp:paragraph {\"c